-- Erzeugt am 2026-11-20 von `python -m scraper.orte.spielstaetten_geo --sql` aus der lokalen
-- Prüfdatei (nur Zeilen mit bestaetigung = ja). Nur die 7 am 20.11.2026 nachgezogenen Orte. Koordinaten von OpenStreetMap (© OpenStreetMap-Mitwirkende),
-- von Google nur die place_id. Stadtteil nur aus der PLZ. Wiederholbar.

BEGIN;

UPDATE public.orte SET adresse = 'Hermannstraße 64, 40233 Düsseldorf', stadtteil = 'Flingern', latitude = 51.2272176, longitude = 6.8090706, google_place_id = COALESCE('ChIJMadXLfvLuEcR15pYK77zNtQ', google_place_id), extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"adresse_bestaetigt": {"datum": "2026-11-20", "quelle": "Website des Hauses"}, "geo_quelle": "osm", "stadt": "Düsseldorf"}'::jsonb) WHERE slug = 'cuvee' AND typ = 'spielstaette';
